import hashlib

def normalize(value):
    return value.lower()

def collect(root):
    rows = []
    for path in sorted(root.glob('*.md')):
        content = path.read_bytes()
        text = content.decode('utf-8', errors='replace')
        rows.append({'path': path.name, 'content': text,
                     'digest': hashlib.sha256(content).hexdigest(),
                     'search': normalize(text), 'mtime': path.stat().st_mtime_ns})
    return rows

from __future__ import annotations
from .documents import normalize
from .store import existing

def query(database, text):
    if not text.strip():
        raise ValueError('query must be nonempty')
    with existing(database) as connection:
        rows = connection.execute('SELECT path FROM documents WHERE instr(search,?) > 0 ORDER BY path', (normalize(text),)).fetchall()
    matches = [{'path': row[0]} for row in rows]
    return {'count': len(matches), 'matches': matches}

from __future__ import annotations
import json
import sqlite3

def decode(text):
    def invalid_constant(value):
        raise ValueError('non-finite JSON number')
    return json.loads(text, parse_constant=invalid_constant)

def value_type(value):
    if value is None:
        return 'null'
    if isinstance(value, bool):
        return 'boolean'
    if isinstance(value, (int, float)):
        return 'number'
    if isinstance(value, str):
        return 'string'
    if isinstance(value, list):
        return 'array'
    if isinstance(value, dict):
        return 'object'
    raise ValueError('unsupported JSON value')

def read_values(database):
    with sqlite3.connect(database.resolve().as_uri() + '?mode=ro', uri=True) as connection:
        connection.row_factory = sqlite3.Row
        version = connection.execute('PRAGMA user_version').fetchone()[0]
        if version not in (1, 2):
            raise ValueError('unsupported schema version')
        rows = connection.execute('SELECT * FROM settings ORDER BY key').fetchall()
        settings = []
        for row in rows:
            value = decode(row['value'])
            settings.append({'key': row['key'], 'value': value,
                             'value_type': row['value_type'] if version == 2 else value_type(value)})
        return {'schema_version': version, 'settings': settings}

